250	// block the pcb task into the block queue
251	void do_block(list_node_t *pcb_node, list_head *queue)
252	{
253	    list_del(pcb_node);
254	    list_add_tail(pcb_node, queue);
255	    list_entry(pcb_node, pcb_t, list)->status = TASK_BLOCKED;
256	}
