258	// unblock the `pcb` from the block queue
259	void do_unblock(list_node_t *pcb_node)
260	{
261	    list_del(pcb_node);
262	    list_add_tail(pcb_node, &ready_queue);
263	    list_entry(pcb_node, pcb_t, list)->status = TASK_READY;
264	    list_entry(pcb_node, pcb_t, list)->ready_tick = get_ticks();
265	}
