9	/*
10	 * Flush entire local TLB.  'sfence.vma' implicitly fences with the instruction
11	 * cache as well, so a 'fence.i' is not necessary.
12	 */
13	static inline void local_flush_tlb_all(void)
14	{
15	    __asm__ __volatile__("sfence.vma" : : : "memory");
16	}
17	
18	/* Flush one page from local TLB */
19	static inline void local_flush_tlb_page(unsigned long addr)
20	{
21	    __asm__ __volatile__("sfence.vma %0" : : "r"(addr) : "memory");
22	}
23	
24	static inline void local_flush_icache_all(void)
25	{
26	    asm volatile("fence.i" ::: "memory");
27	}
28	
29	static inline void local_flush_dcache_all(void)
30	{
31	    dmb();
32	}
