57	#define EI_NIDENT 16
58	typedef struct elf64_hdr
59	{
60	    unsigned char e_ident[EI_NIDENT]; /* ELF "magic number" */
61	    Elf64_Half e_type;
62	    Elf64_Half e_machine;
63	    Elf64_Word e_version;
64	    Elf64_Addr e_entry; /* Entry point virtual address */
65	    Elf64_Off e_phoff;  /* Program header table file offset */
66	    Elf64_Off e_shoff;  /* Section header table file offset */
