76	/* These constants define the permissions on sections in the
77	   program header, p_flags. */
78	#define PF_X (1 << 0)          /* Segment is executable */
79	#define PF_W (1 << 1)          /* Segment is writable */
80	#define PF_R (1 << 2)          /* Segment is readable */
81	#define PF_MASKOS 0x0ff00000   /* OS-specific */
82	#define PF_MASKPROC 0xf0000000 /* Processor-specific */
83	
84	/* Legal values for p_type (segment type).  */
85	
86	#define PT_NULL 0          /* Program header table entry unused */
87	#define PT_LOAD 1          /* Loadable program segment */
88	#define PT_DYNAMIC 2       /* Dynamic linking information */
89	#define PT_INTERP 3        /* Program interpreter */
90	#define PT_NOTE 4          /* Auxiliary information */
91	#define PT_SHLIB 5         /* Reserved */
92	#define PT_PHDR 6          /* Entry for header table itself */
93	#define PT_TLS 7           /* Thread-local storage segment */
94	#define PT_NUM 8           /* Number of defined types */
95	#define PT_LOOS 0x60000000 /* Start of OS-specific */
96	#define PT_GNU_EH_FRAME                     \
97	    0x6474e550 /* GCC .eh_frame_hdr segment \
98	                */
99	#define PT_GNU_STACK                                             \
100	    0x6474e551                  /* Indicates stack executability \
101	                                 */
102	#define PT_GNU_RELRO 0x6474e552 /* Read-only after relocation */
103	#define PT_LOSUNW 0x6ffffffa
104	#define PT_SUNWBSS 0x6ffffffa   /* Sun Specific segment */
105	#define PT_SUNWSTACK 0x6ffffffb /* Stack segment */
106	#define PT_HISUNW 0x6fffffff
107	#define PT_HIOS 0x6fffffff   /* End of OS-specific */
108	#define PT_LOPROC 0x70000000 /* Start of processor-specific */
109	#define PT_HIPROC 0x7fffffff /* End of processor-specific */
