52	int check_duplicate(Records* self, const char* str)
53	{
54	    for (int i = 0; i < self->size; ++i) {
55	        if (strcmp(self->record[i][0], str) == 0) {
56	            return 0;
57	        }
58	    }
59	    return 1;
60	}
