// returns pa
ptr_t alloc_user_page(uint8_t pin, PTE* pgtable)
{
    int i;
    for(i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid == 0){
            break;
        }
    }
    if(i == USER_PAGE_NUM){
        // no free user page: swap a victim out to the disk
        ptr_t victim = selete_page();
        write_to_sd(victim);
        i = pa2num(victim);
    }
    user_page[i].valid = 1;
    user_page[i].pin = pin;
    user_page[i].pgtable = pgtable;
    return num2pa(i);
}

// select a user page to write to disk (NRU), returns pa
ptr_t selete_page()
{
    // NRU: prefer a valid, unpinned page whose PTE accessed bit is clear;
    // clear the accessed bit of the pages we skip (second chance)
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid && !user_page[i].pin){
            PTE *pte = user_page[i].pgtable;
            if(pte == NULL || !get_attribute(*pte, _PAGE_ACCESSED)){
                return num2pa(i);
            }
            clear_attribute(pte, _PAGE_ACCESSED);
        }
    }
    // every candidate was recently used: take the first unpinned one
    for(int i = 0; i < USER_PAGE_NUM; i++){
        if(user_page[i].valid && !user_page[i].pin){
            return num2pa(i);
        }
    }
    // no swappable page at all
    assert(0);
    return 0;
}

void write_to_sd(ptr_t pa)
{
    int num = pa2num(pa);
    // find a free swap slot on the disk
    int i;
    for(i = 0; i < DISK_PAGE_NUM; i++){
        if(disk_page[i].valid == 0){
            break;
        }
    }
    assert(i != DISK_PAGE_NUM);
    disk_page[i].valid = 1;
    // write the page to the swap area: 8 sectors (512B) per page
    sbi_sd_write((unsigned int)pa, PAGE_SIZE / 512,
                 SWAP_BEGIN + i * (PAGE_SIZE / 512));
    // mark the owner's PTE as swapped: not present, slot id in the pfn field
    PTE *pte = user_page[num].pgtable;
    if(pte != NULL){
        clear_attribute(pte, _PAGE_PRESENT);
        set_pfn(pte, i);
        set_attribute(pte, _PAGE_SOFT);
    }
    user_page[num].valid = 0;
    user_page[num].pin = 0;
    user_page[num].pgtable = NULL;
    local_flush_tlb_all();
}

