PTE* init_page_table()
{
    // allocate a fresh pgdir (pa) and share the kernel mapping with it
    PTE *pgdir = alloc_pgdir_page();
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    PTE *kernel_pgdir_kva = (PTE*)pa2kva(PGDIR_PA);
    // 0xffffffc0_00000000 ~ : VPN2 = 0x101, 2MB-large-page kernel mapping
    pgdir_kva[0x101] = kernel_pgdir_kva[0x101];

    // allocate and map the user stack: 0xf_0000_f000 ~ 0xf_0001_0000
    uintptr_t va = USER_STACK_ADDR - PAGE_SIZE;
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;

    PTE *second_level_pgdir = alloc_pgdir_page();
    set_pfn(pgdir_kva + VPN2, (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
    set_attribute(pgdir_kva + VPN2, _PAGE_PRESENT);

    PTE *second_level_kva = (PTE*)pa2kva((uintptr_t)second_level_pgdir);
    PTE *last_level_pgdir = alloc_pgdir_page();
    set_pfn(second_level_kva + VPN1, (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
    set_attribute(second_level_kva + VPN1, _PAGE_PRESENT);

    PTE *last_level_kva = (PTE*)pa2kva((uintptr_t)last_level_pgdir);
    ptr_t user_stack_pa = alloc_user_page(1, last_level_kva + VPN0);
    set_pfn(last_level_kva + VPN0, user_stack_pa >> NORMAL_PAGE_SHIFT);
    set_attribute(last_level_kva + VPN0, _PAGE_PRESENT);
    set_attribute(last_level_kva + VPN0, _PAGE_READ);
    set_attribute(last_level_kva + VPN0, _PAGE_WRITE);
    set_attribute(last_level_kva + VPN0, _PAGE_EXEC);
    set_attribute(last_level_kva + VPN0, _PAGE_USER);
    set_attribute(last_level_kva + VPN0, _PAGE_ACCESSED);
    set_attribute(last_level_kva + VPN0, _PAGE_DIRTY);

    return pgdir;
}

void free_process_user_page(PTE* pgdir)
{
    if(pgdir == NULL){
        return;
    }
    PTE *pgdir_kva = (PTE*)pa2kva((uintptr_t)pgdir);
    for(int i = 0; i < NUM_PTE_ENTRY; i++){
        // the kernel mapping (VPN2 = 0x101) is shared, never free it
        if(i == 0x101 || !get_attribute(pgdir_kva[i], _PAGE_PRESENT)){
            continue;
        }
        PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[i]));
        for(int j = 0; j < NUM_PTE_ENTRY; j++){
            if(!get_attribute(second_level_kva[j], _PAGE_PRESENT)){
                continue;
            }
            PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[j]));
            for(int k = 0; k < NUM_PTE_ENTRY; k++){
                PTE pte = last_level_kva[k];
                if(get_attribute(pte, _PAGE_PRESENT)){
                    uintptr_t pa = get_pa(pte);
                    // shared-memory pages are owned by shm_page[]
                    int s;
                    for(s = 0; s < SHM_PAGE_NUM; s++){
                        if(shm_page[s].count > 0 && shm_page[s].pa == pa){
                            shm_page[s].count--;
                            if(shm_page[s].count == 0){
                                free_user_page(pa);
                                shm_page[s].pa = 0;
                            }
                            break;
                        }
                    }
                    if(s == SHM_PAGE_NUM){
                        free_user_page(pa);
                    }
                }
                else if(get_attribute(pte, _PAGE_SOFT)){
                    // the page lives in the swap area: free its disk slot
                    disk_page[get_pfn(pte)].valid = 0;
                }
            }
            free_pgdir_page(kva2pa((uintptr_t)last_level_kva));
        }
        free_pgdir_page(kva2pa((uintptr_t)second_level_kva));
    }
    free_pgdir_page((uintptr_t)pgdir);
}

// pgdir is pa. if va is not mapped, then mapped it
uintptr_t alloc_page_helper(uintptr_t va, uintptr_t pgdir)
{
    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;

    // build the intermediate levels on demand
    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
        PTE *second_level_pgdir = alloc_pgdir_page();
        set_pfn(pgdir_kva + VPN2, (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(pgdir_kva + VPN2, _PAGE_PRESENT);
    }
    PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
    if(!get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
        PTE *last_level_pgdir = alloc_pgdir_page();
        set_pfn(second_level_kva + VPN1, (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(second_level_kva + VPN1, _PAGE_PRESENT);
    }
    PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));

    // map a freshly allocated user page if the leaf is not present
    if(!get_attribute(last_level_kva[VPN0], _PAGE_PRESENT)){
        ptr_t pa = alloc_user_page(0, last_level_kva + VPN0);
        set_pfn(last_level_kva + VPN0, pa >> NORMAL_PAGE_SHIFT);
        set_attribute(last_level_kva + VPN0, _PAGE_PRESENT);
        set_attribute(last_level_kva + VPN0, _PAGE_READ);
        set_attribute(last_level_kva + VPN0, _PAGE_WRITE);
        set_attribute(last_level_kva + VPN0, _PAGE_EXEC);
        set_attribute(last_level_kva + VPN0, _PAGE_USER);
        set_attribute(last_level_kva + VPN0, _PAGE_ACCESSED);
        set_attribute(last_level_kva + VPN0, _PAGE_DIRTY);
    }
    return get_kva_of(va, pgdir);
}

// shared-memory pages live at 0x0_0000_1000 ~ 0x0_0001_0000
#define SHM_BASE 0x1000lu

uintptr_t shm_page_get(int key)
{
    disable_preempt();
    int i = key % SHM_PAGE_NUM;
    // first user of this key: allocate the physical shared page
    if(shm_page[i].count == 0){
        shm_page[i].pa = alloc_user_page(1, NULL);
        memset((void*)pa2kva(shm_page[i].pa), 0, PAGE_SIZE);
    }
    shm_page[i].count++;

    // map the shared page into the current process's address space
    uintptr_t va = SHM_BASE + i * PAGE_SIZE;
    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;

    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
        PTE *second_level_pgdir = alloc_pgdir_page();
        set_pfn(pgdir_kva + VPN2, (uintptr_t)second_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(pgdir_kva + VPN2, _PAGE_PRESENT);
    }
    PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
    if(!get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
        PTE *last_level_pgdir = alloc_pgdir_page();
        set_pfn(second_level_kva + VPN1, (uintptr_t)last_level_pgdir >> NORMAL_PAGE_SHIFT);
        set_attribute(second_level_kva + VPN1, _PAGE_PRESENT);
    }
    PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
    set_pfn(last_level_kva + VPN0, shm_page[i].pa >> NORMAL_PAGE_SHIFT);
    set_attribute(last_level_kva + VPN0, _PAGE_PRESENT);
    set_attribute(last_level_kva + VPN0, _PAGE_READ);
    set_attribute(last_level_kva + VPN0, _PAGE_WRITE);
    set_attribute(last_level_kva + VPN0, _PAGE_USER);
    set_attribute(last_level_kva + VPN0, _PAGE_ACCESSED);
    set_attribute(last_level_kva + VPN0, _PAGE_DIRTY);

    local_flush_tlb_all();
    enable_preempt();
    return va;
}

void shm_page_dt(uintptr_t addr)
{
    disable_preempt();
    int i = (addr - SHM_BASE) / PAGE_SIZE;

    // unmap the page from the current process's address space
    uintptr_t va = ROUNDDOWN(addr, PAGE_SIZE);
    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;
    if(get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
        PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
        if(get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
            PTE *last_level_kva = (PTE*)pa2kva(get_pa(second_level_kva[VPN1]));
            last_level_kva[VPN0] = 0;
        }
    }

    if(i >= 0 && i < SHM_PAGE_NUM && shm_page[i].count > 0){
        shm_page[i].count--;
        // last user of this shared page: release the physical page
        if(shm_page[i].count == 0){
            free_user_page(shm_page[i].pa);
            shm_page[i].pa = 0;
        }
    }
    local_flush_tlb_all();
    enable_preempt();
}

void handle_page_fault(regs_context_t *regs, uint64_t stval, uint64_t cause)
{
    uintptr_t va = stval & VA_MASK;
    uintptr_t pgdir = (uintptr_t)current_running[cpu_id]->pgdir;
    PTE *pgdir_kva = (PTE*)pa2kva(pgdir);
    int VPN2 = (va >> VPN2_SHIFT) & VPN_MASK;
    int VPN1 = (va >> VPN1_SHIFT) & VPN_MASK;
    int VPN0 = (va >> VPN0_SHIFT) & VPN_MASK;

    // the va has never been mapped: demand paging
    if(!get_attribute(pgdir_kva[VPN2], _PAGE_PRESENT)){
        alloc_page_helper(va, pgdir);
        local_flush_tlb_all();
        return;
    }
    PTE *second_level_kva = (PTE*)pa2kva(get_pa(pgdir_kva[VPN2]));
    if(!get_attribute(second_level_kva[VPN1], _PAGE_PRESENT)){
