    }

    // remove it from whatever queue it is in and hand the pcb
    // to the kernel's cleanup list (see the main loop)
    list_del(&kill_pcb->list);
    kill_pcb->status = TASK_ZOMBIE;
    kill_pcb->mode = AUTO_CLEANUP_ON_EXIT;
    list_add_tail(&kill_pcb->list, &kernel_pcb[0].wait_list);

    enable_preempt();
    return 1;
}

int do_waitpid(pid_t pid, reg_t ignore1, reg_t ignore2, reg_t ignore3, regs_context_t *regs)
{
    disable_preempt();

    // search the pcb
    pcb_t *wait_pcb = NULL;
    for(int i = 0; i < NUM_MAX_TASK; i++){
        if(pcb[i].pid == pid){
            wait_pcb = &pcb[i];
            break;
        }
    }
    if(wait_pcb == NULL){
        enable_preempt();
        return 0;
    }

    // block until it becomes a zombie
    while(wait_pcb->status != TASK_ZOMBIE){
        do_block(&current_running[cpu_id]->list, &wait_pcb->wait_list);
        scheduler();
    }

    // reap it: free the address space it still owns
    if(wait_pcb->pgdir != NULL){
        free_process_user_page(wait_pcb->pgdir);
        wait_pcb->pgdir = NULL;
    }
    // hand the pcb to the kernel's cleanup list (see the main loop);
    // AUTO_CLEANUP_ON_EXIT tasks are already queued by do_exit/do_kill
    if(wait_pcb->mode == ENTER_ZOMBIE_ON_EXIT){
        list_add_tail(&wait_pcb->list, &kernel_pcb[0].wait_list);
    }

    enable_preempt();
    return pid;
}

