args.new_string:
list_node_t* max_priority_node(void)
{
    // highest priority wins; ties are broken by the earliest ready_tick,
    // and only tasks whose hart mask covers this core are eligible
    list_node_t *best = NULL;
    pcb_t *best_pcb = NULL;
    list_node_t *node = ready_queue.next;
    while(node != &ready_queue){
        pcb_t *p = list_entry(node, pcb_t, list);
        if(p->mask & (1lu << cpu_id)){
            if(best == NULL ||
               p->priority > best_pcb->priority ||
               (p->priority == best_pcb->priority &&
                p->ready_tick < best_pcb->ready_tick)){
                best = node;
                best_pcb = p;
            }
        }
        node = node->next;
    }
    return best;
}

